            "description": "当前空气质量等级。",
            "sampleValue": "良"
          }
        }
      }
    },
    "event": {
      "countdownNumber": {
        "type": "string",
        "description": "距离赛事开始的可变倒计时数字。",
        "sampleValue": "15"
